-- Only admin application commands can mutate access/policies using the control connection.
CREATE FUNCTION custom_dim.reject_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'Immutable record: append a new version' USING ERRCODE='42501'; END $$;
CREATE TRIGGER immutable_audit_logs BEFORE UPDATE OR DELETE ON custom_dim.audit_logs FOR EACH ROW EXECUTE FUNCTION custom_dim.reject_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON custom_dim.audit_logs FROM dim_app, service_role;
CREATE TRIGGER immutable_content_versions BEFORE UPDATE OR DELETE ON custom_dim.content_versions FOR EACH ROW EXECUTE FUNCTION custom_dim.reject_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON custom_dim.content_versions FROM dim_app, service_role;
CREATE TRIGGER immutable_content_approvals BEFORE UPDATE OR DELETE ON custom_dim.content_approvals FOR EACH ROW EXECUTE FUNCTION custom_dim.reject_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON custom_dim.content_approvals FROM dim_app, service_role;
CREATE TRIGGER immutable_publication_metrics BEFORE UPDATE OR DELETE ON custom_dim.publication_metrics FOR EACH ROW EXECUTE FUNCTION custom_dim.reject_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON custom_dim.publication_metrics FROM dim_app, service_role;
CREATE TRIGGER immutable_influencer_personas BEFORE UPDATE OR DELETE ON custom_dim.influencer_personas FOR EACH ROW EXECUTE FUNCTION custom_dim.reject_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON custom_dim.influencer_personas FROM dim_app, service_role;
CREATE TRIGGER immutable_consent_records BEFORE UPDATE OR DELETE ON custom_dim.consent_records FOR EACH ROW EXECUTE FUNCTION custom_dim.reject_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON custom_dim.consent_records FROM dim_app, service_role;
CREATE TRIGGER immutable_identity_consents BEFORE UPDATE OR DELETE ON custom_dim.identity_consents FOR EACH ROW EXECUTE FUNCTION custom_dim.reject_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON custom_dim.identity_consents FROM dim_app, service_role;
